// Condense one captured session JSONL to the turns a lesson pass reads:
// human prose turns whole, assistant prose truncated, tool calls as one line each.
// usage: node condense.mjs <file> [assistantChars] [toolChars]
import { createReadStream } from 'node:fs';
import { createInterface } from 'node:readline';

const [file, aChars = '1400', tChars = '160'] = process.argv.slice(2);
const AC = Number(aChars), TC = Number(tChars);
const clip = (s, n) => (s.length > n ? s.slice(0, n) + ` …[+${s.length - n}]` : s);
const flat = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

const rl = createInterface({ input: createReadStream(file), crlfDelay: Infinity });
for await (const line of rl) {
  if (!line.trim()) continue;
  let e; try { e = JSON.parse(line); } catch { continue; }
  const t = (e.timestamp || '').slice(11, 19);
  const m = e.message;
  if (!m) continue;
  const content = Array.isArray(m.content) ? m.content : [{ type: 'text', text: m.content }];
  if (m.role === 'user') {
    const texts = content.filter((c) => c.type === 'text').map((c) => flat(c.text)).filter(Boolean);
    for (const x of texts) console.log(`\n[${t}] HUMAN: ${x}`);
    for (const c of content) {
      if (c.type !== 'tool_result') continue;
      const body = flat(typeof c.content === 'string' ? c.content
        : Array.isArray(c.content) ? c.content.map((p) => p.text ?? '').join(' ') : '');
      if (c.is_error) console.log(`[${t}]   ERR< ${clip(body, TC * 3)}`);
    }
  } else if (m.role === 'assistant') {
    for (const c of content) {
      if (c.type === 'text' && flat(c.text)) console.log(`[${t}] AI: ${clip(flat(c.text), AC)}`);
      else if (c.type === 'tool_use') console.log(`[${t}]   > ${c.name}(${clip(flat(JSON.stringify(c.input)), TC)})`);
    }
  }
}

